 const [loading,setLoading]=useState(true),[pending,setPending]=useState(false),[error,setError]=useState(""),[toast,setToast]=useState(""),[mobile,setMobile]=useState(false),[board,setBoard]=useState(false),[kindFilter,setKindFilter]=useState("");
 const [editor,setEditor]=useState<Draft|null>(null),[selected,setSelected]=useState<string|null>(null),[detail,setDetail]=useState<Details|null>(null),[dialog,setDialog]=useState<string|null>(null),[manage,setManage]=useState<Partial<Topic>|null>(null),[invite,setInvite]=useState("");
