 const range=monthRange(day),memberName=(id:string|null)=>data?.members.find(x=>x.user_id===id)?.name??data?.people?.find(x=>x.user_id===id)?.name??"미지정";
 const me=data?.members.find(x=>x.user_id===user?.userId),isAdmin=!!me&&["owner","admin"].includes(me.role),canWrite=!!me&&me.role!=="viewer"&&!data?.workspace.archived;
 const presence=usePresence(workspace,editor?.id??selected,!!editor,!!user&&!!data);
