 useEffect(()=>{const timer=setTimeout(()=>setDebounced(search),250);return()=>clearTimeout(timer)},[search]);
 const loadSpaces=useCallback(async()=>{if(!user)return;try{const result=await api<{workspaces:Workspace[]}>("/api/data");setSpaces(result.workspaces);const linked=new URLSearchParams(location.search).get("workspace");setWorkspace(old=>(result.workspaces.some(s=>s.id===old)?old:"")||result.workspaces.find(s=>s.id===(linked??localStorage.getItem("daybook-workspace")))?.id||result.workspaces[0]?.id||"");setLoading(false)}catch(e){setError((e as Error).message);setLoading(false)}},[user]);
 useEffect(()=>{void loadSpaces();const code=new URLSearchParams(location.search).get("invite");if(code){setInvite(code);setDialog("join")}},[loadSpaces]);
