 useEffect(()=>{if(data&&workspace){const params=new URLSearchParams(location.search),entry=params.get("entry");if(entry){setSelected(entry);params.delete("entry");history.replaceState(null,"",location.pathname+(params.size?"?"+params.toString():""))}}},[!!data,workspace]);
 const loadDetail=useCallback(async()=>{if(!selected||!workspace)return;try{const result=await api<Details>(`/api/data?workspace=${encodeURIComponent(workspace)}&entry=${encodeURIComponent(selected)}`);if(workspaceRef.current===workspace&&selectedRef.current===selected)setDetail(result)}catch(e){flash((e as Error).message)}},[workspace,selected,flash]);
 useEffect(()=>{setDetail(null);void loadDetail();const timer=setInterval(()=>{if(document.visibilityState==="visible")void loadDetail()},5000);return()=>clearInterval(timer)},[loadDetail]);
 async function post(payload:Record<string,unknown>,refresh=true){if(writeLock.current)throw new Error("진행 중인 작업이 끝나면 다시 시도하세요.");writeLock.current=true;setPending(true);try{const result=await api<{id:string;workspace:string;token:string;count:number;pending?:boolean}>("/api/data",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({workspace,...payload})});if(refresh)await reload(true);return result}catch(e){flash((e as Error).message);throw e}finally{writeLock.current=false;setPending(false)}}
 const run=(fn:()=>Promise<unknown>)=>{void fn().catch(()=>{})};
 function navigate(next:View){setView(next);setTopic("");setCustom("");setKindFilter("");setMobile(false);setSearch("")}
