 useEffect(()=>{const key=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();searchInput.current?.focus()}};window.addEventListener("keydown",key);return()=>window.removeEventListener("keydown",key)},[]);
