 async function saveEntry(draft:Draft,files:File[]){const result=await post({...draft,action:draft.id?"update":"create"});let uploadError=false;for(const file of files){try{await upload(file,result.id,false)}catch{uploadError=true}}setEditor(null);setImported(null);await reload(true);setSelected(result.id);flash(uploadError?"기록은 저장됐지만 일부 첨부에 실패했습니다. 기록에서 다시 올려주세요.":"기록을 저장했습니다.")}
