 async function importFile(file:File){try{const document=await readDocument(file);setImported({file,document});setEditor({kind:"note",title:document.title,body:document.body,day,project_id:project||null,topic_id:topic||null,custom_type_id:custom||null,status:"todo",priority:"normal"})}catch(e){flash((e as Error).message)}}
 async function deleteEntry(entry:Entry){if(!confirm(`‘${entry.title}’ 기록을 휴지통으로 옮길까요?`))return;await post({action:"delete",id:entry.id,version:entry.version});setSelected(null);flash("휴지통으로 옮겼습니다.")}
 async function backup(){try{const result=await api(`/api/data?workspace=${encodeURIComponent(workspace)}&mode=export`);const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:"application/json"}));const a=document.createElement("a");a.href=url;a.download=`daybook-${dayOf()}.json`;a.click();URL.revokeObjectURL(url);flash("백업 파일을 저장했습니다.")}catch(e){flash((e as Error).message)}}
 const live=data?.entries.filter(e=>!e.deleted_at)??[];
