 const tasks=filtered.filter(e=>e.kind==="task"),dayRecords=filtered.filter(e=>e.day===day&&e.kind!=="chat"),todayTasks=tasks.filter(e=>e.status!=="done"&&(e.day<=day||!!e.due_day&&e.due_day<=day)).sort((a,b)=>(a.due_day??"9999").localeCompare(b.due_day??"9999"));
